import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int romanToInt(String s) {
        Map<Character, Integer> romanNumerals = new HashMap<>();
        romanNumerals.put('I', 1);
        romanNumerals.put('V', 5);
        romanNumerals.put('X', 10);
        romanNumerals.put('L', 50);
        romanNumerals.put('C', 100);
        romanNumerals.put('D', 500);
        romanNumerals.put('M', 1000);

        int result = 0;
        for (int i = 0; i < s.length(); i++) {
            if (i > 0 && romanNumerals.get(s.charAt(i)) > romanNumerals.get(s.charAt(i - 1))) {
                result += romanNumerals.get(s.charAt(i)) - 2 * romanNumerals.get(s.charAt(i - 1));
            } else {
                result += romanNumerals.get(s.charAt(i));
            }
        }

        return result;
    }

    public static void main(String[] args) {
        Solution solution = new Solution();
        System.out.println(solution.romanToInt("III"));  // 3
        System.out.println(solution.romanToInt("LVIII"));  // 58
        System.out.println(solution.romanToInt("MCMXCIV"));  // 1994
    }
}
