class Solution {
    /**
     * Converts a Roman numeral to an integer.
     *
     * @param s The Roman numeral string.
     * @return The integer representation of the Roman numeral.
     */
    public int romanToInt(String s) {
        int result = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int currentValue = c - '0';
            if (currentValue < 1 || currentValue > 9) {
                return -1;
            }
            result += currentValue;
        }
        return result;
    }
}
