class Solution {
    /**
     * Checks if the input string is valid.
     *
     * @param s The input string.
     * @return True if the input string is valid, false otherwise.
     */
    public boolean isValid(String s) {
        if (s == null || s.length() == 0) {
            return true;
        }

        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(' || c == '{' || c == '[' && balance < 2) {
                balance++;
            } else {
                balance--;
            }
        }

        return balance == 0;
    }
}
