import java.util.Arrays;

class Solution {
    /**
     * Maximizes profit by choosing a single day to buy one stock and choosing a different day in the future to sell that stock.
     *
     * @param prices The array of prices.
     * @return The maximum profit achievable from this transaction.
     */
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int[] dp = new int[n];
        dp[0] = 0;

        for (int i = 1; i < n; i++) {
            dp[i] = dp[i - 1];
            int profit = prices[i] - prices[i - 1];
            if (profit > 0) {
                dp[i] = Math.max(dp[i], profit);
            }
        }

        return dp[n - 1];
    }
}
